#include <bits/stdc++.h>
using namespace std;

int main() {
    // 6 位数以内：59049 * 6
    const int LIMIT = 59049 * 6;
    for (int x = 1; x <= LIMIT; x++) {
        int t = x, sum = 0;
        while (t) {
            int d = t % 10;
            sum += d * d * d * d * d;
            t /= 10;
        }
        if (sum == x) cout << x << "\n";
    }
    return 0;
}

