#include <bits/stdc++.h>
using namespace std;

int main() {
    string n;
    int k;
    cin >> n >> k;
    vector<pair<int, int>> rules(k);
    for (auto &r : rules) cin >> r.first >> r.second;

    bool can[10];
    for (int d = 0; d < 10; d++) can[d] = true;   // 0 次变换

    // 规则可级联：反复松弛，最多 10 轮（每次至少新增一个数字）
    for (int round = 0; round < 10; round++) {
        bool changed = false;
        for (auto &r : rules) {
            if (can[r.first] && !can[r.second]) {
                can[r.second] = true;
                changed = true;
            }
        }
        if (!changed) break;
    }

    int cnt = 0;
    for (int d = 0; d < 10; d++) if (can[d]) cnt++;

    long long ans = 1;
    for (char ch : n) ans *= cnt;
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    int size = 2 * n - 1;
    vector<string> g(size, string(size, '.'));
    int center = n - 1;

    const int dx[8] = {-1, -1, -1, 0, 0, 1, 1, 1};
    const int dy[8] = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int k = 0; k < 8; k++) {
        int r = center, c = center;
        int letter = n - 1;                       // 0 = 'A'
        while (true) {
            if (r >= 0 && r < size && c >= 0 && c < size) {
                g[r][c] = char('A' + letter);
            } else {
                break;
            }
            r += dx[k];
            c += dy[k];
            letter--;
            if (letter < 0) break;
        }
    }

    for (const string &row : g) cout << row << "\n";
    return 0;
}
